// Service worker — lets the app open with no signal (2026-08-26).
//
// Hand-written rather than generated by a build plugin: this app already ships
// a manifest and icons, so a service worker was the only missing piece, and
// ~60 lines with no new dependency beats adding a build-time plugin to
// maintain. Data offline is handled separately in src/offline.js — this file
// only deals with getting the app itself to load.
//
// STRATEGY, and why it's safe:
//
//   Navigations  -> network first, cached index.html as fallback.
//                   Online you always get the newest build; offline you get
//                   the last one that loaded.
//
//   Hashed assets -> cache first.
//                   Vite fingerprints these (index-a1b2c3.js), so a given URL
//                   is immutable — caching it forever can't go stale. A new
//                   deploy produces new filenames, which the freshly fetched
//                   index.html points at. This is what avoids the classic
//                   "service worker serves a white screen after deploy" trap.
//
//   Supabase/API -> never touched. Those go straight to the network and, on
//                   failure, into offline.js's cache-and-queue layer. A
//                   service worker caching API responses on top of that would
//                   be two sources of truth arguing with each other.

const VERSION = 'v1'
const SHELL_CACHE = `cl-maintenance-shell-${VERSION}`
const ASSET_CACHE = `cl-maintenance-assets-${VERSION}`

self.addEventListener('install', (event) => {
  // Take over as soon as possible — on first install there's no old worker to
  // conflict with, and crew shouldn't have to close every tab to get offline
  // support working.
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(['/', '/index.html', '/manifest.json'])).then(() => self.skipWaiting())
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k !== SHELL_CACHE && k !== ASSET_CACHE).map((k) => caches.delete(k)))
      )
      .then(() => self.clients.claim())
  )
})

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET') return

  const url = new URL(req.url)

  // Anything not served by this app (Supabase, the slip-parsing endpoint,
  // Yoco) is left entirely alone.
  if (url.origin !== self.location.origin) return

  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone()
          caches.open(SHELL_CACHE).then((c) => c.put('/index.html', copy))
          return res
        })
        .catch(() => caches.match('/index.html').then((r) => r || Response.error()))
    )
    return
  }

  event.respondWith(
    caches.match(req).then((hit) => {
      if (hit) return hit
      return fetch(req)
        .then((res) => {
          // Only cache real successes. A 404 or an opaque redirect cached
          // here would be served forever.
          if (res && res.status === 200 && res.type === 'basic') {
            const copy = res.clone()
            caches.open(ASSET_CACHE).then((c) => c.put(req, copy))
          }
          return res
        })
        .catch(() => hit || Response.error())
    })
  )
})
